```javascript
require('dotenv').config();
const express = require('express');
const router = express.Router();
const { body, param, query } = require('express-validator');
const cors = require('cors');
const { v4: uuidv4 } = require('uuid');

const app = express();

app.use(cors());
app.use(express.json());

let todos = [];

// GET all todos
router.get('/todos', async (req, res) => {
  const filteredTodos = todos.filter(todo => 
    req.query.completed === 'true' ? todo.completed : todo
  );

  return res.json(filteredTodos);
});

// GET single todo
router.get('/todos/:id', async (req, res) => {
  const todo = todos.find(t => t.id === req.params.id);
  if (!todo) return res.status(404).json({ error: 'Todo not found' });

  return res.json(todo);
});

// POST new todo validation
const todoValidators = [
  body('title').exists().isString().isLength({ min: 1, max: 100 })
];

router.post('/todos', ...todoValidators, async (req, res) => {
  const { title } = req.body;

  if (!title) return res.status(400).json({ error: 'Title is required' });

  const newTodo = {
    id: uuidv4(),
    title,
    completed: false,
    createdAt: Date.now(),
    updatedAt: Date.now()
  };

  todos.push(newTodo);

  return res.status(201).json(newTodo);
});

// PUT update todo
router.put('/todos/:id', async (req, res) => {
  const { title } = req.body;
  const todoIndex = todos.findIndex(t => t.id === req.params.id);

  if (!title && !req.body.completed) return res.status(400).json({ error: 'No fields to update' });

  if (todoIndex < 0) return res.status(404).json({ error: 'Todo not found' });

  let updatedTodo = {
    ...todos[todoIndex],
    title,
    completed: req.body.completed || todos[todoIndex].completed,
    updatedAt: Date.now()
  };

  if (title && title.length > 100) return res.status(400).json({ error: 'Title too long' });

  updatedTodo = { ...updatedTodo };

  todos[todoIndex] = updatedTodo;

  return res.json(updatedTodo);
});

// DELETE todo
router.delete('/todos/:id', async (req, res) => {
  const todoIndex = todos.findIndex(t => t.id === req.params.id);

  if (todoIndex < 0) return res.status(404).json({ error: 'Todo not found' });

  const deletedTodo = todos.splice(todoIndex, 1)[0];

  return res.json(deletedTodo);
});

// Error handling middleware
app.use((err, req, res, next) => {
  if (err.statusCode) {
    res.status(err.statusCode).json({ error: err.message });
  } else {
    console.error('Unexpected error:', err);
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

app.use('/api', router);

const port = process.env.PORT || 3000;
app.listen(port, () => {
  console.log(`Server running on port ${port}`);
});

module.exports = app;
