require('supertest');
const request = require('supertest');
const app = require('./app');

describe('Todo API', () => {
  let server;

  beforeEach(() => {
    server = app.listen();
  });

  afterEach((done) => {
    server.close(done);
  });

  describe('GET /api/todos', () => {
    it('should get all todos', async () => {
      const response = await request(app).get('/api/todos');
      expect(response.statusCode).toBe(200);
    });
  });

  describe('POST /api/todos', () => {
    it('should create a todo with valid title', async () => {
      const response = await request(app)
        .post('/api/todos')
        .send({ title: 'Test Todo' });
      expect(response.statusCode).toBe(201);
      expect(response.body.title).toBe('Test Todo');
    });

    it('should return error for invalid title', async () => {
      const response = await request(app)
        .post('/api/todos')
        .send({ title: '' });
      expect(response.statusCode).toBe(400);
    });
  });

  describe('PUT /api/todos/:id', () => {
    it('should update a todo', async () => {
      const createResponse = await request(app)
        .post('/api/todos')
        .send({ title: 'Test Todo' });

      const response = await request(app)
        .put(`/api/todos/${createResponse.body.id}`)
        .send({ completed: true });
      expect(response.statusCode).toBe(200);
      expect(response.body.completed).toBe(true);
    });
  });

  describe('DELETE /api/todos/:id', () => {
    it('should delete a todo', async () => {
      const createResponse = await request(app)
        .post('/api/todos')
        .send({ title: 'Test Todo' });

      const response = await request(app)
        .delete(`/api/todos/${createResponse.body.id}`);
      expect(response.statusCode).toBe(200);
    });
  });

  describe('Error Cases', () => {
    it('should return 404 for missing todo', async () => {
      const response = await request(app).get('/api/todos/123');
      expect(response.statusCode).toBe(404);
    });
  });
});
